"""Plain-text absence notices for parents."""

from typing import Iterable

from rosterkit.models import Mark, Student

Marks = Iterable[Mark]
ABSENT = "absent"

class NoticeError(ValueError):
    """The marks cannot be turned into a notice."""

def check_owner(student: Student, marks: list) -> None:
    for mark in marks:
        if mark.student_id != student.student_id:
            raise NoticeError(
                f"mark belongs to {mark.student_id}"
            )

def absent_days(student: Student, marks: Marks) -> list:
    """Sorted, distinct days the student was absent."""
    marks = list(marks)
    check_owner(student, marks)
    gone = [item for item in marks if item.status == ABSENT]
    return sorted({item.day for item in gone})

def full_name(student: Student) -> str:
    return f"{student.first_name} {student.last_name}"

def plural(count: int) -> str:
    return "1 day" if count == 1 else f"{count} days"

def compose(student: Student, days: list) -> str:
    dates = ", ".join(item.isoformat() for item in days)
    return (
        f"{full_name(student)} missed {plural(len(days))}: "
        f"{dates}."
    )

def build_notice(student: Student, marks: Marks) -> str:
    """Short notice naming the student, count and dates."""
    days = absent_days(student, marks)
    if not days:
        raise NoticeError("no absences to report")
    return compose(student, days)

