# owner: platform
import unittest

from rosterkit.notices import NoticeError, build_notice
from rosterkit.models import Mark, Student
from datetime import date

PUPIL = Student("s1", "Lovelace", "Ada", "A")

def mark(when, status="absent", pupil="s1"):
    return Mark(pupil, date(2026, 9, when), status)

class BuildNoticeTests(unittest.TestCase):
    def test_names_count_and_ordered_dates(self):
        marks = [mark(9), mark(3), mark(4, "present")]
        text = build_notice(PUPIL, marks)
        self.assertEqual(
            text,
            "Ada Lovelace missed 2 days: "
            "2026-09-03, 2026-09-09."
        )

    def test_single_day(self):
        text = build_notice(PUPIL, [mark(3)])
        self.assertIn("missed 1 day:", text)

    def test_repeated_day_counts_once(self):
        text = build_notice(PUPIL, [mark(3), mark(3)])
        self.assertIn("missed 1 day:", text)

    def test_other_students_mark(self):
        marks = [mark(3), mark(4, pupil="s2")]
        with self.assertRaises(NoticeError):
            build_notice(PUPIL, marks)

    def test_no_absences(self):
        with self.assertRaises(NoticeError):
            build_notice(PUPIL, [mark(3, "late")])

    def test_no_marks(self):
        with self.assertRaises(NoticeError):
            build_notice(PUPIL, [])
